-- Migration number: 0001 	 2026-11-03T21:43:01.771Z
--
-- Initial schema: users, catalogue, credits, genre, ratings.
-- See ARCHITECTURE.md §3.
--
-- Conventions used throughout:
--
--   * Primary keys are UUIDs generated by the application
--     (crypto.randomUUID()), stored as TEXT. External IDs are nullable and
--     unique where present.
--   * Tables are STRICT, so a value of the wrong type is an error rather than
--     being silently coerced.
--   * Enumerations are CHECK constraints. Adding a value means rebuilding the
--     table, which is acceptable while the dataset is small.
--   * Calendar dates of musical facts (release dates) are stored as ISO 8601
--     prefixes whose length matches their precision: '1982', '1982-11',
--     '1982-11-30'. That makes them sort and compare correctly as text, so
--     "released from 2015" is simply `>= '2015'`. Each is paired with a
--     date_precision column, and a CHECK keeps the two consistent.
--   * System timestamps (created_at, rated_at) are always exact and stored as
--     UTC ISO 8601 with milliseconds. They need no precision column.
--   * Polymorphic references (entity_type, entity_id) cannot carry a foreign
--     key, so triggers check that the referenced row exists.
--   * Nothing in this schema is ever deleted by the application (merges
--     reparent and redirect), so foreign keys use the default NO ACTION,
--     which makes an accidental delete fail loudly.


-- ---------------------------------------------------------------------------
-- Users
-- ---------------------------------------------------------------------------

-- Rows are created on first authenticated visit. Cloudflare Access holds the
-- allowlist; this table only gives each identity a stable local id.
CREATE TABLE app_user (
    id            TEXT PRIMARY KEY NOT NULL,
    email         TEXT NOT NULL UNIQUE COLLATE NOCASE,
    display_name  TEXT NOT NULL CHECK (display_name <> ''),
    is_owner      INTEGER NOT NULL DEFAULT 0 CHECK (is_owner IN (0, 1)),
    created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

-- Exactly one owner: the person whose ratings the public site shows.
CREATE UNIQUE INDEX app_user_one_owner ON app_user (is_owner) WHERE is_owner = 1;


-- ---------------------------------------------------------------------------
-- Catalogue
-- ---------------------------------------------------------------------------

CREATE TABLE artist (
    id              TEXT PRIMARY KEY NOT NULL,
    name            TEXT NOT NULL CHECK (name <> ''),
    sort_name       TEXT NOT NULL CHECK (sort_name <> ''),
    disambiguation  TEXT,
    mbid            TEXT UNIQUE,
    spotify_id      TEXT UNIQUE,
    discogs_id      TEXT UNIQUE,
    source          TEXT NOT NULL
                    CHECK (source IN ('musicbrainz', 'spotify', 'discogs', 'files', 'manual')),
    created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE INDEX artist_name ON artist (name COLLATE NOCASE);
CREATE INDEX artist_sort_name ON artist (sort_name COLLATE NOCASE);


-- A composition, shared by every recording of it. The link that lets
-- versions of one song collapse to a single result.
CREATE TABLE work (
    id                      TEXT PRIMARY KEY NOT NULL,
    title                   TEXT NOT NULL CHECK (title <> ''),
    preferred_recording_id  TEXT,
    mbid                    TEXT UNIQUE,
    source                 TEXT NOT NULL
                            CHECK (source IN ('musicbrainz', 'spotify', 'discogs', 'files', 'manual')),
    created_at              TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),

    -- The preferred recording must be a recording of this work. Composite
    -- key against recording (id, work_id); not checked while NULL.
    FOREIGN KEY (preferred_recording_id, id) REFERENCES recording (id, work_id)
) STRICT;


-- Track ratings attach here. A remix or live take is its own recording.
CREATE TABLE recording (
    id                  TEXT PRIMARY KEY NOT NULL,
    work_id             TEXT REFERENCES work (id),
    title               TEXT NOT NULL CHECK (title <> ''),
    length_ms           INTEGER CHECK (length_ms > 0),
    first_release_date  TEXT,
    date_precision      TEXT NOT NULL DEFAULT 'unknown',
    mbid                TEXT UNIQUE,
    spotify_id          TEXT UNIQUE,
    -- CC-XXX-YY-NNNNN without hyphens. Written as three short GLOBs because
    -- D1 caps pattern length.
    isrc                TEXT CHECK (length(isrc) = 12
                                    AND isrc NOT GLOB '*[^A-Z0-9]*'
                                    AND substr(isrc, 6) NOT GLOB '*[^0-9]*'),
    source              TEXT NOT NULL
                        CHECK (source IN ('musicbrainz', 'spotify', 'discogs', 'files', 'manual')),
    created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),

    -- Target for work.preferred_recording_id.
    UNIQUE (id, work_id),

    CHECK (
        (date_precision = 'unknown' AND first_release_date IS NULL) OR
        (date_precision = 'year'    AND first_release_date GLOB '[0-9][0-9][0-9][0-9]') OR
        (date_precision = 'month'   AND first_release_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]') OR
        (date_precision = 'day'     AND first_release_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'
                                    AND date(first_release_date) = first_release_date)
    )
) STRICT;

CREATE INDEX recording_work ON recording (work_id);
CREATE INDEX recording_title ON recording (title COLLATE NOCASE);
-- Not unique: MusicBrainz has ISRCs shared across distinct recordings.
CREATE INDEX recording_isrc ON recording (isrc);


-- An album in the abstract. Album ratings attach here, so every edition
-- counts once. May have no releases at all (an announced album).
CREATE TABLE release_group (
    id                    TEXT PRIMARY KEY NOT NULL,
    title                 TEXT NOT NULL CHECK (title <> ''),
    type                  TEXT NOT NULL
                          CHECK (type IN ('album', 'ep', 'single', 'compilation', 'mixtape', 'soundtrack', 'live')),
    status                TEXT NOT NULL DEFAULT 'released'
                          CHECK (status IN ('announced', 'released', 'cancelled')),
    -- NULL means not yet known. No import source reports this, and defaulting
    -- to for_sale would hide records from the "unpurchasable" list.
    availability          TEXT
                          CHECK (availability IN ('for_sale', 'unpurchasable', 'unreleased')),
    first_release_date    TEXT,
    date_precision        TEXT NOT NULL DEFAULT 'unknown',
    preferred_release_id  TEXT,
    mbid                  TEXT UNIQUE,
    spotify_id            TEXT UNIQUE,
    source                TEXT NOT NULL
                          CHECK (source IN ('musicbrainz', 'spotify', 'discogs', 'files', 'manual')),
    created_at            TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),

    -- The preferred release must be an edition of this group.
    FOREIGN KEY (preferred_release_id, id) REFERENCES release (id, release_group_id),

    CHECK (
        (date_precision = 'unknown' AND first_release_date IS NULL) OR
        (date_precision = 'year'    AND first_release_date GLOB '[0-9][0-9][0-9][0-9]') OR
        (date_precision = 'month'   AND first_release_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]') OR
        (date_precision = 'day'     AND first_release_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'
                                    AND date(first_release_date) = first_release_date)
    )
) STRICT;

CREATE INDEX release_group_title ON release_group (title COLLATE NOCASE);
CREATE INDEX release_group_first_release_date ON release_group (first_release_date);


-- One edition of a release group: a pressing, reissue, regional or deluxe.
CREATE TABLE release (
    id                TEXT PRIMARY KEY NOT NULL,
    release_group_id  TEXT NOT NULL REFERENCES release_group (id),
    title             TEXT NOT NULL CHECK (title <> ''),
    date              TEXT,
    date_precision    TEXT NOT NULL DEFAULT 'unknown',
    country           TEXT CHECK (length(country) = 2),
    label             TEXT,
    format            TEXT,
    -- R2 key prefix for cover art derivatives ({art_key}/{size}.jpg).
    -- NULL means no art has been stored yet.
    art_key           TEXT,
    mbid              TEXT UNIQUE,
    spotify_id        TEXT UNIQUE,
    source            TEXT NOT NULL
                      CHECK (source IN ('musicbrainz', 'spotify', 'discogs', 'files', 'manual')),
    created_at        TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),

    -- Target for release_group.preferred_release_id.
    UNIQUE (id, release_group_id),

    CHECK (
        (date_precision = 'unknown' AND date IS NULL) OR
        (date_precision = 'year'    AND date GLOB '[0-9][0-9][0-9][0-9]') OR
        (date_precision = 'month'   AND date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]') OR
        (date_precision = 'day'     AND date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'
                                    AND date(date) = date)
    )
) STRICT;

CREATE INDEX release_release_group ON release (release_group_id);


-- A recording's appearance on a release.
CREATE TABLE track (
    id                TEXT PRIMARY KEY NOT NULL,
    release_id        TEXT NOT NULL REFERENCES release (id),
    recording_id      TEXT NOT NULL REFERENCES recording (id),
    disc              INTEGER NOT NULL DEFAULT 1 CHECK (disc >= 1),
    position          INTEGER NOT NULL CHECK (position >= 1),
    title_on_release  TEXT,

    UNIQUE (release_id, disc, position)
) STRICT;

CREATE INDEX track_recording ON track (recording_id);


-- ---------------------------------------------------------------------------
-- Credits
-- ---------------------------------------------------------------------------

CREATE TABLE artist_credit (
    id           TEXT PRIMARY KEY NOT NULL,
    entity_type  TEXT NOT NULL
                 CHECK (entity_type IN ('release_group', 'release', 'recording')),
    entity_id    TEXT NOT NULL,
    artist_id    TEXT NOT NULL REFERENCES artist (id),
    role         TEXT NOT NULL
                 CHECK (role IN ('primary', 'featured', 'remixer', 'producer', 'writer',
                                 'engineer', 'performer', 'mixer')),
    -- Order within (entity, role): first-listed primary artist is position 1.
    position     INTEGER NOT NULL DEFAULT 1 CHECK (position >= 1),
    -- How the artist is named on this entity, when it differs from
    -- artist.name ("Prince" credited as "The Artist").
    credited_as  TEXT CHECK (credited_as <> ''),
    -- Text after this artist when the credit is displayed: ' & ', ' feat. '.
    join_phrase  TEXT NOT NULL DEFAULT '',

    UNIQUE (entity_type, entity_id, artist_id, role)
) STRICT;

CREATE INDEX artist_credit_entity ON artist_credit (entity_type, entity_id, role, position);
CREATE INDEX artist_credit_artist ON artist_credit (artist_id, role, entity_type);


-- ---------------------------------------------------------------------------
-- Genre
-- ---------------------------------------------------------------------------

-- A tree. Queries walk it with recursive CTEs. Cycle prevention is the
-- application's job: SQLite does not allow CTEs inside triggers.
CREATE TABLE genre (
    id         TEXT PRIMARY KEY NOT NULL,
    name       TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK (name <> ''),
    parent_id  TEXT REFERENCES genre (id),

    CHECK (parent_id <> id)
) STRICT;

CREATE INDEX genre_parent ON genre (parent_id);


-- Manual and derived tags for the same genre can coexist on one entity;
-- recomputing derived rows never touches manual ones.
CREATE TABLE genre_tag (
    entity_type  TEXT NOT NULL CHECK (entity_type IN ('release_group', 'recording')),
    entity_id    TEXT NOT NULL,
    genre_id     TEXT NOT NULL REFERENCES genre (id),
    source       TEXT NOT NULL CHECK (source IN ('manual', 'derived', 'musicbrainz', 'discogs')),
    -- For derived tags, the share of tracks carrying the genre (0.4 to 1.0
    -- under the current threshold), which gives the ordering. 1 for manual.
    weight       REAL NOT NULL DEFAULT 1 CHECK (weight > 0 AND weight <= 1),

    PRIMARY KEY (entity_type, entity_id, genre_id, source)
) STRICT;

CREATE INDEX genre_tag_genre ON genre_tag (genre_id, entity_type);


-- ---------------------------------------------------------------------------
-- Ratings
-- ---------------------------------------------------------------------------

-- Append-only. The current rating is the latest row per
-- (user, entity). Each row is a complete snapshot, not a patch.
-- A detailed row may also carry gut_score; those rows are what
-- v_gut_calibration learns from.
CREATE TABLE rating (
    id           TEXT PRIMARY KEY NOT NULL,
    user_id      TEXT NOT NULL REFERENCES app_user (id),
    entity_type  TEXT NOT NULL CHECK (entity_type IN ('recording', 'release_group')),
    entity_id    TEXT NOT NULL,
    rated_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    depth        TEXT NOT NULL CHECK (depth IN ('gut', 'detailed')),

    gut_score    REAL CHECK (gut_score   BETWEEN 0 AND 10),

    -- Craft axes: recordings only.
    production   REAL CHECK (production  BETWEEN 0 AND 10),
    songwriting  REAL CHECK (songwriting BETWEEN 0 AND 10),
    lyrics       REAL CHECK (lyrics      BETWEEN 0 AND 10),
    performance  REAL CHECK (performance BETWEEN 0 AND 10),

    -- Album axes: release groups only.
    sequencing   REAL CHECK (sequencing  BETWEEN 0 AND 10),
    cohesion     REAL CHECK (cohesion    BETWEEN 0 AND 10),
    ambition     REAL CHECK (ambition    BETWEEN 0 AND 10),

    -- Deliberately sparse. Not a quality measure.
    impact       REAL CHECK (impact      BETWEEN 0 AND 10),
    impact_note  TEXT CHECK (impact_note <> ''),

    -- "Latest row" must be unambiguous.
    UNIQUE (user_id, entity_type, entity_id, rated_at),

    CHECK (entity_type = 'recording' OR
           (production IS NULL AND songwriting IS NULL AND lyrics IS NULL AND performance IS NULL)),
    CHECK (entity_type = 'release_group' OR
           (sequencing IS NULL AND cohesion IS NULL AND ambition IS NULL)),

    -- depth must describe the row truthfully: a gut rating is a gut score
    -- and nothing else on the axes; a detailed rating has at least one axis.
    CHECK (
        (depth = 'gut' AND gut_score IS NOT NULL
            AND coalesce(production, songwriting, lyrics, performance,
                         sequencing, cohesion, ambition) IS NULL)
        OR
        (depth = 'detailed'
            AND coalesce(production, songwriting, lyrics, performance,
                         sequencing, cohesion, ambition) IS NOT NULL)
    )
) STRICT;

-- Serves "latest rating per user and entity" and rating history.
CREATE INDEX rating_entity ON rating (entity_type, entity_id, user_id, rated_at);


-- Rating rows are immutable. The one exception is entity_id, which a merge
-- reparents onto the surviving entity so both histories combine.
CREATE TRIGGER rating_no_update
BEFORE UPDATE OF id, user_id, entity_type, rated_at, depth, gut_score,
                 production, songwriting, lyrics, performance,
                 sequencing, cohesion, ambition, impact, impact_note
ON rating
BEGIN
    SELECT RAISE(ABORT, 'rating rows are append-only');
END;

CREATE TRIGGER rating_no_delete
BEFORE DELETE ON rating
BEGIN
    SELECT RAISE(ABORT, 'rating rows are append-only');
END;


-- Versioned composite weights. Historical versions are kept so old rankings
-- can be replayed.
CREATE TABLE weights (
    id            TEXT PRIMARY KEY NOT NULL,
    user_id       TEXT NOT NULL REFERENCES app_user (id),
    version      INTEGER NOT NULL CHECK (version >= 1),
    payload_json  TEXT NOT NULL CHECK (json_valid(payload_json)),
    active        INTEGER NOT NULL DEFAULT 0 CHECK (active IN (0, 1)),
    created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),

    UNIQUE (user_id, version)
) STRICT;

-- At most one active weights version per user.
CREATE UNIQUE INDEX weights_one_active ON weights (user_id) WHERE active = 1;


-- ---------------------------------------------------------------------------
-- Polymorphic reference checks
-- ---------------------------------------------------------------------------

CREATE TRIGGER artist_credit_entity_exists_insert
BEFORE INSERT ON artist_credit
WHEN NOT CASE NEW.entity_type
    WHEN 'release_group' THEN EXISTS (SELECT 1 FROM release_group WHERE id = NEW.entity_id)
    WHEN 'release'       THEN EXISTS (SELECT 1 FROM release       WHERE id = NEW.entity_id)
    WHEN 'recording'     THEN EXISTS (SELECT 1 FROM recording     WHERE id = NEW.entity_id)
END
BEGIN
    SELECT RAISE(ABORT, 'artist_credit references a missing entity');
END;

CREATE TRIGGER artist_credit_entity_exists_update
BEFORE UPDATE OF entity_type, entity_id ON artist_credit
WHEN NOT CASE NEW.entity_type
    WHEN 'release_group' THEN EXISTS (SELECT 1 FROM release_group WHERE id = NEW.entity_id)
    WHEN 'release'       THEN EXISTS (SELECT 1 FROM release       WHERE id = NEW.entity_id)
    WHEN 'recording'     THEN EXISTS (SELECT 1 FROM recording     WHERE id = NEW.entity_id)
END
BEGIN
    SELECT RAISE(ABORT, 'artist_credit references a missing entity');
END;

CREATE TRIGGER genre_tag_entity_exists_insert
BEFORE INSERT ON genre_tag
WHEN NOT CASE NEW.entity_type
    WHEN 'release_group' THEN EXISTS (SELECT 1 FROM release_group WHERE id = NEW.entity_id)
    WHEN 'recording'     THEN EXISTS (SELECT 1 FROM recording     WHERE id = NEW.entity_id)
END
BEGIN
    SELECT RAISE(ABORT, 'genre_tag references a missing entity');
END;

CREATE TRIGGER genre_tag_entity_exists_update
BEFORE UPDATE OF entity_type, entity_id ON genre_tag
WHEN NOT CASE NEW.entity_type
    WHEN 'release_group' THEN EXISTS (SELECT 1 FROM release_group WHERE id = NEW.entity_id)
    WHEN 'recording'     THEN EXISTS (SELECT 1 FROM recording     WHERE id = NEW.entity_id)
END
BEGIN
    SELECT RAISE(ABORT, 'genre_tag references a missing entity');
END;

CREATE TRIGGER rating_entity_exists_insert
BEFORE INSERT ON rating
WHEN NOT CASE NEW.entity_type
    WHEN 'release_group' THEN EXISTS (SELECT 1 FROM release_group WHERE id = NEW.entity_id)
    WHEN 'recording'     THEN EXISTS (SELECT 1 FROM recording     WHERE id = NEW.entity_id)
END
BEGIN
    SELECT RAISE(ABORT, 'rating references a missing entity');
END;

CREATE TRIGGER rating_entity_exists_update
BEFORE UPDATE OF entity_id ON rating
WHEN NOT CASE NEW.entity_type
    WHEN 'release_group' THEN EXISTS (SELECT 1 FROM release_group WHERE id = NEW.entity_id)
    WHEN 'recording'     THEN EXISTS (SELECT 1 FROM recording     WHERE id = NEW.entity_id)
END
BEGIN
    SELECT RAISE(ABORT, 'rating references a missing entity');
END;
